@Override
public boolean afterBpmCompleteActivity(ApproveFundVoucherQueryDTO dto) {
    // 一次性查询凭证和凭证头信息，避免重复查询
    Map<String, Object> voucherInfo = getVoucherWithHeaderById(dto.getAccountHeaderId());
    List<TmsLoanAccount> tmsLoanAccounts = (List<TmsLoanAccount>) voucherInfo.get("accounts");
    TmsLoanAccountHeader header = (TmsLoanAccountHeader) voucherInfo.get("header");

    if (Collections3.isEmpty(tmsLoanAccounts)) {
        throw new WebException("依据业务ID:{}未查询到分录信息,请刷新后再操作.", dto.getAccountHeaderId());
