        if (data.getAttribute5Name() != null) {
            sb.append(data.getAttribute5Name()).append(",");
        }
        if (data.getAttribute6Name() != null) {
            sb.append(data.getAttribute6Name());
        }
        String result = sb.toString();
        // 去除末尾可能存在的逗号
        if (result.endsWith(",")) {
            result = result.substring(0, result.length() - 1);
        }
